1	<!doctype html>
2	<html lang="ja">
3	  <head>
4	    <meta charset="utf-8" />
5	    <meta name="viewport" content="width=device-width, initial-scale=1" />
6	    <title>翻訳支援（CAT）ツール — 画面サンプル</title>
7	    <style>
8	      :root {
9	        --bg: #f6f7f9;
10	        --card: #ffffff;
11	        --fg: #0f172a;
12	        --muted-fg: #64748b;
13	        --muted: #f1f5f9;
14	        --border: #e2e8f0;
15	        --border-strong: #cbd5e1;
16	        --primary: #0f172a;
17	        --primary-fg: #ffffff;
18	        --accent: #2563eb;
19	        --accent-soft: #eff6ff;
20	        --green: #16a34a;
21	        --green-soft: #f0fdf4;
22	        --amber: #d97706;
23	        --amber-soft: #fffbeb;
24	        --violet: #7c3aed;
25	        --violet-soft: #f5f3ff;
26	        --radius: 10px;
27	        --shadow: 0 1px 2px rgba(15,23,42,.06), 0 1px 3px rgba(15,23,42,.04);
28	      }
29	      * { box-sizing: border-box; }
30	      html, body { margin: 0; padding: 0; }
31	      body {
32	        background: var(--bg); color: var(--fg);
33	        font-family: "Inter", system-ui, -apple-system, "Segoe UI", "Hiragino Kaku Gothic ProN", "Noto Sans JP", sans-serif;
34	        font-size: 14px; line-height: 1.6;
35	      }
36	      /* ---- mock switcher ---- */
37	      .switcher {
38	        position: sticky; top: 0; z-index: 50;
39	        display: flex; align-items: center; gap: 10px;
40	        padding: 10px 18px; background: #0b1220; color: #e2e8f0; border-bottom: 1px solid #1e293b;
41	      }
42	      .switcher .brand { font-weight: 700; font-size: 13px; letter-spacing: .02em; margin-right: 8px; color: #93c5fd; }
43	      .switcher button {
44	        background: transparent; color: #cbd5e1; border: 1px solid #1e293b; border-radius: 8px;
45	        padding: 6px 14px; font-size: 13px; cursor: pointer; font-family: inherit;
46	      }
47	      .switcher button.active { background: #1d4ed8; color: #fff; border-color: #1d4ed8; }
48	      .switcher .note { margin-left: auto; font-size: 12px; color: #64748b; }
49	
50	      .screen { display: none; }
51	      .screen.active { display: block; }
52	
53	      /* ---- app chrome ---- */
54	      .app { display: grid; grid-template-columns: 220px 1fr; min-height: calc(100vh - 45px); }
55	      .sidebar { background: var(--card); border-right: 1px solid var(--border); padding: 18px 14px; }
56	      .sidebar .logo { display: flex; align-items: center; gap: 9px; font-weight: 700; font-size: 15px; padding: 4px 8px 16px; }
57	      .sidebar .logo .dot { width: 22px; height: 22px; border-radius: 6px; background: var(--accent); display: inline-flex; align-items: center; justify-content: center; color: #fff; font-size: 12px; }
58	      .nav-item { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; color: var(--muted-fg); cursor: pointer; font-size: 13.5px; }
59	      .nav-item.active { background: var(--muted); color: var(--fg); font-weight: 600; }
60	      .nav-item .ic { width: 16px; text-align: center; opacity: .8; }
61	      .sidebar .group-label { font-size: 11px; text-transform: uppercase; letter-spacing: .08em; color: #94a3b8; padding: 16px 10px 6px; }
62	      .content { padding: 26px 32px; overflow: auto; }
63	
64	      .topbar { display: flex; align-items: center; gap: 14px; margin-bottom: 22px; }
65	      .topbar h1 { font-size: 21px; margin: 0; }
66	      .breadcrumb { font-size: 12.5px; color: var(--muted-fg); margin-bottom: 6px; }
67	      .breadcrumb a { color: var(--accent); text-decoration: none; }
68	      .spacer { flex: 1; }
69	
70	      /* ---- atoms ---- */
71	      .btn { display: inline-flex; align-items: center; gap: 7px; border-radius: 8px; padding: 8px 14px; font-size: 13px; cursor: pointer; border: 1px solid var(--border-strong); background: var(--card); color: var(--fg); font-family: inherit; }
72	      .btn:hover { background: var(--muted); }
73	      .btn.primary { background: var(--primary); color: var(--primary-fg); border-color: var(--primary); }
74	      .btn.primary:hover { background: #1e293b; }
75	      .btn.accent { background: var(--accent); color: #fff; border-color: var(--accent); }
76	      .btn.accent:hover { background: #1d4ed8; }
77	      .btn.sm { padding: 5px 10px; font-size: 12px; }
78	      .btn.ghost { border-color: transparent; background: transparent; }
79	      .btn.ghost:hover { background: var(--muted); }
80	
81	      .badge { display: inline-flex; align-items: center; gap: 5px; font-size: 11.5px; padding: 2px 9px; border-radius: 999px; border: 1px solid var(--border); font-weight: 500; }
82	      .badge .d { width: 6px; height: 6px; border-radius: 50%; }
83	      .badge.public { background: var(--accent-soft); color: var(--accent); border-color: #bfdbfe; }
84	      .badge.private { background: var(--muted); color: var(--muted-fg); }
85	      .badge.green { background: var(--green-soft); color: var(--green); border-color: #bbf7d0; }
86	      .badge.amber { background: var(--amber-soft); color: var(--amber); border-color: #fde68a; }
87	      .badge.slate { background: var(--muted); color: var(--muted-fg); }
88	
89	      .input { width: 100%; border: 1px solid var(--border-strong); border-radius: 8px; padding: 8px 12px; font-size: 13.5px; font-family: inherit; color: var(--fg); background: var(--card); }
90	      .input:focus { outline: 2px solid var(--accent-soft); border-color: var(--accent); }
91	      .search { position: relative; }
92	      .search .ic { position: absolute; left: 11px; top: 50%; transform: translateY(-50%); color: #94a3b8; font-size: 13px; }
93	      .search input { padding-left: 32px; }
94	
95	      .progress { height: 7px; background: var(--muted); border-radius: 999px; overflow: hidden; }
96	      .progress > span { display: block; height: 100%; background: var(--green); border-radius: 999px; }
97	      .progress.accent > span { background: var(--accent); }
98	
99	      .avatar { width: 26px; height: 26px; border-radius: 50%; background: #ddd; display: inline-flex; align-items: center; justify-content: center; font-size: 11px; color: #fff; font-weight: 600; border: 2px solid #fff; }
100	
101	      /* ---- project list ---- */
102	      .grid-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 16px; }
103	      .pcard { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow); cursor: pointer; transition: border-color .15s; }
104	      .pcard:hover { border-color: var(--border-strong); }
105	      .pcard .row1 { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
106	      .pcard h3 { margin: 0; font-size: 15.5px; }
107	      .pcard .desc { color: var(--muted-fg); font-size: 12.5px; margin: 10px 0 0; min-height: 38px; }
108	
109	      /* ---- detail ---- */
110	      .tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--border); margin: 18px 0 20px; }
111	      .tab { padding: 9px 16px; font-size: 13.5px; color: var(--muted-fg); cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -1px; }
112	      .tab.active { color: var(--fg); border-bottom-color: var(--primary); font-weight: 600; }
113	      .tabpane { display: none; }
114	      .tabpane.active { display: block; }
115	
116	      table.list { width: 100%; border-collapse: collapse; background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }
117	      table.list th, table.list td { padding: 12px 14px; text-align: left; border-bottom: 1px solid var(--border); font-size: 13px; }
118	      table.list th { background: #fafbfc; color: var(--muted-fg); font-weight: 600; font-size: 11.5px; text-transform: uppercase; letter-spacing: .04em; }
119	      table.list tr:last-child td { border-bottom: none; }
120	      table.list tbody tr:hover { background: #fafbfc; }
121	      .seg-prog { display: flex; align-items: center; gap: 8px; min-width: 150px; }
122	      .seg-prog .progress { flex: 1; }
123	      .seg-prog span.num { font-size: 11.5px; color: var(--muted-fg); white-space: nowrap; }
124	
125	      .panel { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px; box-shadow: var(--shadow); }
126	      .kv { display: grid; grid-template-columns: auto 1fr; gap: 6px 18px; font-size: 13px; }
127	      .kv dt { color: var(--muted-fg); }
128	
129	      /* ---- editor ---- */
130	      .editor-wrap { display: flex; height: calc(100vh - 45px); }
131	      .editor-main { display: flex; flex-direction: column; flex: 1 1 50%; min-width: 300px; background: var(--bg); }
132	      .resizer { flex: 0 0 6px; cursor: col-resize; background: var(--border); position: relative; }
133	      .resizer::after { content: "⋮"; position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); color: #94a3b8; font-size: 14px; }
134	      .resizer:hover, .resizer.active { background: var(--accent); }
135	      .editor-bar { display: flex; align-items: center; gap: 14px; padding: 12px 22px; background: var(--card); border-bottom: 1px solid var(--border); }
136	      .editor-bar .wname { font-weight: 600; font-size: 14.5px; }
137	      .editor-bar .save { font-size: 12px; color: var(--green); display: flex; align-items: center; gap: 5px; }
138	      .editor-scroll { overflow: auto; padding: 16px 22px 60px; }
139	      .seg {
140	        display: grid; grid-template-columns: 34px 1fr 1fr; gap: 0;
141	        background: var(--card); border: 1px solid var(--border); border-radius: 8px; margin-bottom: 5px; overflow: hidden;
142	        cursor: pointer; transition: box-shadow .15s, border-color .15s;
143	      }
144	      .seg:hover { border-color: var(--border-strong); }
145	      .seg.selected { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
146	      .seg .no { background: #fafbfc; border-right: 1px solid var(--border); color: #94a3b8; font-size: 11.5px; display: flex; flex-direction: column; align-items: center; gap: 5px; padding-top: 8px; font-variant-numeric: tabular-nums; }
147	      .seg .no .st-dot { width: 8px; height: 8px; border-radius: 50%; }
148	      .seg .src { padding: 7px 14px; font-size: 13px; line-height: 1.55; border-right: 1px solid var(--border); color: #1e293b; }
149	      .seg .tgt { padding: 4px 8px; position: relative; display: flex; align-items: center; }
150	      .seg .tgt textarea {
151	        width: 100%; border: none; resize: none; font-family: inherit; font-size: 13px; line-height: 1.55; color: #0f172a;
152	        background: transparent; padding: 3px 6px; min-height: 22px; outline: none;
153	      }
154	      .seg .tgt textarea::placeholder { color: #cbd5e1; }
155	      .seg-head { display: grid; grid-template-columns: 34px 1fr 1fr; padding: 0 0 6px; font-size: 11px; color: #94a3b8; text-transform: uppercase; letter-spacing: .05em; }
156	      .seg-head div { padding: 0 14px; }
157	      /* operation field (right) */
158	      .op-bar { background: #fafbfc; }
159	      .op-row { display: flex; align-items: center; gap: 8px; }
160	      .op-actions { display: flex; gap: 8px; margin-top: 10px; }
161	      /* merge mode */
162	      .merge-bar { display: none; align-items: center; gap: 12px; padding: 9px 22px; background: #fff7ed; border-bottom: 1px solid #fed7aa; font-size: 13px; color: #9a3412; }
163	      .merge-bar.on { display: flex; }
164	      .merge-bar .mb-count { font-weight: 600; }
165	      .editor-scroll.merge-mode .seg { cursor: copy; }
166	      .editor-scroll.merge-mode .seg .tgt textarea { pointer-events: none; background: transparent; }
167	      .editor-scroll.merge-mode .seg:hover { border-color: var(--accent); }
168	      .seg.merge-selected { border-color: var(--accent) !important; background: var(--accent-soft); box-shadow: 0 0 0 2px var(--accent-soft); }
169	      .seg.merge-selected .no { background: var(--accent-soft); color: var(--accent); font-weight: 700; }
170	      .btn.sm.toggled { background: #fff7ed; border-color: #fed7aa; color: #9a3412; }
171	      /* split mode */
172	      .split-bar { display: none; align-items: center; gap: 12px; padding: 9px 22px; background: #fffbeb; border-bottom: 1px solid #fde68a; font-size: 13px; color: #92400e; }
173	      .split-bar.on { display: flex; }
174	      .editor-scroll.split-mode .seg { cursor: default; }
175	      .editor-scroll.split-mode .seg .tgt textarea { pointer-events: none; background: transparent; }
176	      .split-here { display: inline-flex; align-items: center; justify-content: center; width: 18px; height: 18px; margin: 0 1px; border-radius: 4px; background: #fef3c7; color: #b45309; font-size: 10px; cursor: pointer; vertical-align: middle; border: 1px solid #fde68a; }
177	      .split-here:hover { background: #f59e0b; color: #fff; }
178	
179	      /* assist panel */
180	      .assist { background: var(--card); border-left: 1px solid var(--border); display: flex; flex-direction: column; overflow: auto; flex: 1 1 50%; min-width: 300px; }
181	      .assist .ahead { padding: 10px 16px; border-bottom: 1px solid var(--border); position: sticky; top: 0; background: var(--card); z-index: 2; }
182	      .assist .ahead .src-echo {
183	        font-size: 12px; color: #1e293b; background: var(--muted); padding: 6px 9px; border-radius: 8px; margin-top: 6px;
184	        display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
185	      }
186	      .asec { padding: 10px 14px; border-bottom: 1px solid var(--border); }
187	      .asec h4 { margin: 0 0 7px; font-size: 12px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted-fg); display: flex; align-items: center; gap: 7px; }
188	      .asec h4 .cnt { background: var(--muted); color: var(--muted-fg); border-radius: 999px; padding: 0 7px; font-size: 11px; }
189	      .ai-candidate { background: var(--accent-soft); border: 1px solid #bfdbfe; border-radius: 8px; padding: 9px 11px; font-size: 12.5px; color: #1e3a8a; }
190	      .ai-actions { display: flex; gap: 8px; margin-top: 8px; }
191	      .tm-item { border: 1px solid var(--border); border-radius: 8px; padding: 7px 10px; margin-bottom: 6px; cursor: pointer; }
192	      .tm-item:hover { background: #fafbfc; border-color: var(--border-strong); }
193	      .tm-item .ja { font-size: 12.5px; color: #475569; }
194	      .tm-item .en { font-size: 12.5px; color: #0f172a; margin-top: 3px; }
195	      .tm-item .meta { display: flex; align-items: center; justify-content: space-between; margin-top: 6px; }
196	      .tm-item .score { font-size: 11px; font-weight: 600; color: var(--green); }
197	      .gl-item { display: flex; align-items: center; gap: 8px; font-size: 12.5px; padding: 4px 0; border-bottom: 1px dashed var(--border); }
198	      .gl-item .ja { color: #475569; }
199	      .gl-item .arr { color: #cbd5e1; }
200	      .gl-item .en { color: #0f172a; font-weight: 500; }
201	      .gl-item .src-flag { margin-left: auto; font-size: 10.5px; color: var(--violet); background: var(--violet-soft); border-radius: 4px; padding: 1px 6px; }
202	
203	      .hint { font-size: 12px; color: var(--muted-fg); }
204	      .empty-assist { padding: 40px 20px; text-align: center; color: #94a3b8; font-size: 13px; }
205	    </style>
206	  </head>
207	  <body>
208	    <!-- ============ mock switcher ============ -->
209	    <div class="switcher">
210	      <span class="brand">CAT MOCKUP</span>
211	      <button data-screen="list" class="active">① プロジェクト一覧</button>
212	      <button data-screen="detail">② プロジェクト詳細</button>
213	      <button data-screen="editor">③ 翻訳エディタ</button>
214	      <button data-screen="glossary">④ 共通用語集</button>
215	      <button data-screen="tm">⑤ 翻訳メモリ</button>
216	      <span class="note">クリックで画面遷移できます（ダミーデータ）</span>
217	    </div>
218	
219	    <!-- ============ ① project list ============ -->
220	    <div class="screen active" id="screen-list">
221	      <div class="app">
222	        <aside class="sidebar">
223	          <div class="logo"><span class="dot">和</span> TransDesk</div>
224	          <div class="nav-item active" onclick="go('list')"><span class="ic">▦</span> プロジェクト</div>
225	          <div class="nav-item" onclick="go('glossary')"><span class="ic">▤</span> 共通用語集</div>
226	          <div class="nav-item" onclick="go('tm')"><span class="ic">◷</span> 翻訳メモリ</div>
227	          <div class="group-label">アカウント</div>
228	          <div class="nav-item"><span class="ic">⚙</span> 設定</div>
229	        </aside>
230	        <main class="content">
231	          <div class="topbar">
232	            <div>
233	              <h1>プロジェクト</h1>
234	              <div class="hint">和文→英訳の翻訳プロジェクトを管理します</div>
235	            </div>
236	            <div class="spacer"></div>
237	            <div class="search" style="width:240px"><span class="ic">⌕</span><input class="input" placeholder="プロジェクトを検索" /></div>
238	            <button class="btn accent">＋ 新規プロジェクト</button>
239	          </div>
240	
241	          <div class="grid-cards">
242	            <div class="pcard" onclick="go('detail')">
243	              <div class="row1"><h3>2026 製品カタログ 英訳</h3><span class="badge private"><span class="d" style="background:#94a3b8"></span>Private</span></div>
244	              <div class="desc">新製品ラインの英語版カタログ。マーケ部門向け。</div>
245	            </div>
246	
247	            <div class="pcard" onclick="go('detail')">
248	              <div class="row1"><h3>社内規程 ハンドブック</h3><span class="badge public"><span class="d" style="background:#2563eb"></span>Public</span></div>
249	              <div class="desc">就業規則・行動規範の英訳。全社共有。</div>
250	            </div>
251	
252	            <div class="pcard" onclick="go('detail')">
253	              <div class="row1"><h3>IR 決算説明資料 Q2</h3><span class="badge private"><span class="d" style="background:#94a3b8"></span>Private</span></div>
254	              <div class="desc">投資家向け説明会の英語スライド。</div>
255	            </div>
256	
257	            <div class="pcard" onclick="go('detail')">
258	              <div class="row1"><h3>Web サイト リニューアル</h3><span class="badge public"><span class="d" style="background:#2563eb"></span>Public</span></div>
259	              <div class="desc">コーポレートサイトの英語ページ原稿。</div>
260	            </div>
261	
262	            <div class="pcard" style="border-style:dashed; display:flex; align-items:center; justify-content:center; color:#94a3b8; min-height:96px;">
263	              ＋ 新しいプロジェクトを作成
264	            </div>
265	          </div>
266	        </main>
267	      </div>
268	    </div>
269	
270	    <!-- ============ ② project detail ============ -->
271	    <div class="screen" id="screen-detail">
272	      <div class="app">
273	        <aside class="sidebar">
274	          <div class="logo"><span class="dot">和</span> TransDesk</div>
275	          <div class="nav-item active" onclick="go('list')"><span class="ic">▦</span> プロジェクト</div>
276	          <div class="nav-item" onclick="go('glossary')"><span class="ic">▤</span> 共通用語集</div>
277	          <div class="nav-item" onclick="go('tm')"><span class="ic">◷</span> 翻訳メモリ</div>
278	          <div class="group-label">アカウント</div>
279	          <div class="nav-item"><span class="ic">⚙</span> 設定</div>
280	        </aside>
281	        <main class="content">
282	          <div class="breadcrumb"><a href="#" onclick="go('list');return false;">プロジェクト</a> / 2026 製品カタログ 英訳</div>
283	          <div class="topbar">
284	            <div>
285	              <h1>2026 製品カタログ 英訳 <span class="badge private" style="vertical-align:middle"><span class="d" style="background:#94a3b8"></span>Private</span></h1>
286	              <div class="hint">新製品ラインの英語版カタログ。マーケ部門向け。</div>
287	            </div>
288	            <div class="spacer"></div>
289	            <div style="display:flex; align-items:center;">
290	              <span class="avatar" style="background:#2563eb; margin-right:-8px">YN</span>
291	              <span class="avatar" style="background:#7c3aed; margin-right:-8px">MK</span>
292	              <span class="avatar" style="background:#16a34a">+3</span>
293	            </div>
294	            <button class="btn">メンバー管理</button>
295	            <button class="btn accent">＋ 新規ワーク</button>
296	          </div>
297	
298	          <div class="tabs">
299	            <div class="tab active" data-tab="works">ワーク <span style="color:#94a3b8">(8)</span></div>
300	            <div class="tab" data-tab="glossary">用語集 <span style="color:#94a3b8">(54)</span></div>
301	            <div class="tab" data-tab="tm">翻訳メモリ <span style="color:#94a3b8">(1,204)</span></div>
302	          </div>
303	
304	          <!-- works tab -->
305	          <div class="tabpane active" data-pane="works">
306	            <table class="list">
307	              <thead><tr><th style="width:34%">ドキュメント</th><th>ステータス</th><th style="width:24%">セグメント進捗</th><th>更新</th><th style="width:90px"></th></tr></thead>
308	              <tbody>
309	                <tr onclick="go('editor')" style="cursor:pointer">
