635	        if (!d) return; // 結合で生成された行などは詳細データを持たない
636	        document.getElementById("ai-cand").textContent = d.ai;
637	        document.getElementById("cur-no").textContent = id;
638	        const st = document.getElementById("cur-status");
639	        st.className = "badge " + d.cls;
640	        st.innerHTML = '<span class="d" style="background:' + d.color + '"></span>' + d.status;
641	      }
642	
643	      function toggleMerge() {
644	        if (splitMode) toggleSplit(); // モードは排他
645	        mergeMode = !mergeMode;
646	        const scroll = document.querySelector(".editor-scroll");
647	        scroll.classList.toggle("merge-mode", mergeMode);
648	        document.getElementById("merge-bar").classList.toggle("on", mergeMode);
649	        document.getElementById("merge-toggle").classList.toggle("toggled", mergeMode);
650	        document.querySelectorAll(".seg.merge-selected").forEach((s) => s.classList.remove("merge-selected"));
651	        updateMergeCount();
652	      }
653	
654	      function updateMergeCount() {
655	        const n = document.querySelectorAll(".seg.merge-selected").length;
656	        const c = document.getElementById("mb-count");
657	        if (c) c.textContent = n + " 文 選択中";
658	        const b = document.getElementById("mb-merge");
659	        if (b) b.disabled = n < 2;
660	      }
661	
662	      function renumber() {
663	        document.querySelectorAll(".editor-scroll .seg").forEach((s, i) => {
664	          const no = s.querySelector(".no");
665	          const dot = no.querySelector(".st-dot");
666	          no.innerHTML = "";
667	          no.appendChild(dot);
668	          no.appendChild(document.createTextNode(String(i + 1)));
669	          s.dataset.id = String(i + 1);
670	        });
671	      }
672	
673	      function doMerge() {
674	        const selected = [...document.querySelectorAll(".seg.merge-selected")];
675	        if (selected.length < 2) return;
676	        const first = selected[0];
677	        // 原文は連結（日本語はそのまま）、訳文は半角スペースで連結
678	        const src = selected.map((s) => s.querySelector(".src").textContent.trim()).join("");
679	        const tgt = selected.map((s) => s.querySelector("textarea").value.trim()).filter(Boolean).join(" ");
680	        first.querySelector(".src").textContent = src;
681	        first.querySelector("textarea").value = tgt;
682	        // 結合後は状態を「下書き」に戻す
683	        const dot = first.querySelector(".st-dot");
684	        dot.style.background = "#d97706";
685	        dot.title = "下書き";
686	        selected.slice(1).forEach((s) => s.remove());
687	        first.classList.remove("merge-selected");
688	        renumber();
689	        updateMergeCount();
690	      }
691	
692	      function toggleSplit() {
693	        if (mergeMode) toggleMerge(); // モードは排他
694	        splitMode = !splitMode;
695	        const scroll = document.querySelector(".editor-scroll");
696	        scroll.classList.toggle("split-mode", splitMode);
697	        document.getElementById("split-bar").classList.toggle("on", splitMode);
698	        document.getElementById("split-toggle").classList.toggle("toggled", splitMode);
699	        if (splitMode) applySplitMarkers();
700	        else clearSplitMarkers();
701	      }
702	
703	      // 各セグメントの原文を文区切り（。！？）で分け、境界に ✂ マーカーを差し込む
704	      function applySplitMarkers() {
705	        document.querySelectorAll(".editor-scroll .seg").forEach((seg) => {
706	          const src = seg.querySelector(".src");
707	          const text = src.dataset.raw || src.textContent;
708	          src.dataset.raw = text;
709	          const parts = text.split(/(?<=[。！？])/).filter((p) => p.length);
710	          src.innerHTML = "";
711	          parts.forEach((p, i) => {
712	            src.appendChild(document.createTextNode(p));
713	            if (i < parts.length - 1) {
714	              const sc = document.createElement("span");
715	              sc.className = "split-here";
716	              sc.textContent = "✂";
717	              sc.title = "ここで分割";
718	              sc.onclick = (e) => {
719	                e.stopPropagation();
720	                doSplit(seg, i);
721	              };
722	              src.appendChild(sc);
723	            }
724	          });
725	        });
726	      }
727	
728	      function clearSplitMarkers() {
729	        document.querySelectorAll(".editor-scroll .seg .src").forEach((src) => {
730	          if (src.dataset.raw) src.textContent = src.dataset.raw;
731	        });
732	      }
733	
734	      function doSplit(seg, idx) {
735	        const src = seg.querySelector(".src");
736	        const text = src.dataset.raw || src.textContent;
737	        const parts = text.split(/(?<=[。！？])/).filter((p) => p.length);
738	        if (parts.length < 2) return;
739	        const firstText = parts.slice(0, idx + 1).join("");
740	        const secondText = parts.slice(idx + 1).join("");
741	        const clone = seg.cloneNode(true);
742	        // 1 文目：原文前半。訳文は元のまま残す
743	        src.dataset.raw = firstText;
744	        src.textContent = firstText;
745	        // 2 文目：原文後半。訳文は空＝未訳に
746	        const cloneSrc = clone.querySelector(".src");
747	        cloneSrc.dataset.raw = secondText;
748	        cloneSrc.textContent = secondText;
749	        clone.classList.remove("selected", "merge-selected");
750	        clone.querySelector("textarea").value = "";
751	        const dot = clone.querySelector(".st-dot");
752	        if (dot) {
753	          dot.style.background = "#94a3b8";
754	          dot.title = "未訳";
755	        }
756	        seg.after(clone);
757	        renumber();
758	        applySplitMarkers(); // 分割後にマーカーを再構築
759	      }
760	
761	      // 翻訳フィールドと操作フィールドの境界をドラッグでリサイズ
762	      (function () {
763	        const resizer = document.getElementById("resizer");
764	        const main = document.querySelector(".editor-main");
765	        const assist = document.getElementById("assist");
766	        const wrap = document.querySelector(".editor-wrap");
767	        if (!resizer) return;
768	        let dragging = false;
769	        resizer.addEventListener("mousedown", (e) => {
770	          dragging = true;
771	          resizer.classList.add("active");
772	          document.body.style.userSelect = "none";
773	          document.body.style.cursor = "col-resize";
774	          e.preventDefault();
775	        });
776	        window.addEventListener("mousemove", (e) => {
777	          if (!dragging) return;
778	          const rect = wrap.getBoundingClientRect();
779	          const min = 300;
780	          let leftW = Math.max(min, Math.min(rect.width - min - 6, e.clientX - rect.left));
781	          main.style.flex = "0 0 " + leftW + "px";
782	          assist.style.flex = "1 1 auto";
783	        });
784	        window.addEventListener("mouseup", () => {
785	          if (!dragging) return;
786	          dragging = false;
787	          resizer.classList.remove("active");
788	          document.body.style.userSelect = "";
789	          document.body.style.cursor = "";
790	        });
791	      })();
792	    </script>
793	  </body>
794	</html>
