12	const cronConfig = v.parse(
13	  v.pipe(
14	    v.union([
15	      v.object({
16	        cronSecret: v.pipe(
17	          v.string("CRON_SECRET は文字列である必要があります"),
18	          v.minLength(1, "CRON_SECRET は必須です"),
19	        ),
20	        environment: v.literal("production"),
21	        vercelUrl: v.pipe(
22	          v.string("VERCEL_URL は文字列である必要があります"),
23	          v.minLength(1, "VERCEL_URL は必須です"),
24	        ),
25	      }),
26	      v.object({
27	        environment: v.literal("preview"),
28	      }),
29	      v.object({
30	        environment: v.optional(v.literal("local"), "local"),
31	      }),
32	    ]),
33	    v.transform((result) => {
34	      const environment = result.environment;
35	      switch (environment) {
36	        case "local":
37	          return { cronSecret: "", url: "http://host.docker.internal:3000" };
38	        case "preview":
39	          return { cronSecret: "", url: "" };
40	        case "production":
41	          return {
42	            cronSecret: result.cronSecret,
43	            url: `https://${result.vercelUrl}`,
44	          };
45	        default:
46	          throw new Error(
47	            `Unexpected environment: ${environment satisfies never}`,
48	          );
49	      }
50	    }),
51	  ),
52	  {
53	    cronSecret: process.env["CRON_SECRET"],
54	    environment: process.env["VERCEL_ENV"],
55	    vercelUrl: process.env["VERCEL_URL"],
56	  },
57	);
58	async function setupPgmqQueue() {
59	  console.log("⭐️ pgmqキュー作成");
60	
61	  await createQueueIfNotExists(ADVICE_QUEUE_NAME);
62	  await createQueueIfNotExists(MEMORY_QUEUE_NAME);
63	}
64	
65	async function setupCronJob() {
66	  console.log("⭐️ pg_cronジョブ設定");
67	
68	  if (!cronConfig.url) {
69	    // preview 環境でも cron スケジュールを設定するとプレビューごとに AI 実行のリクエストが飛ぶようになってしまい
70	    // リクエスト数を消費しすぎてしまうためジョブは設定しない
71	    // デメリットとしてプレビュー環境では自動で AI 生成ができない
72	    // 手動で /api/cron/generate-* にリクエストを投げることで対応可能
73	    console.log("⏩️ pg_cronジョブ設定をスキップ");
74	    return;
75	  }
76	
77	  // ローカル環境では1分ごと、本番環境では10分ごと
78	  // ローカル環境ではリクエスト数が多くても問題ないので DX を考慮して短い間隔に
79	  const isLocal = cronConfig.cronSecret === "";
80	  const schedule = isLocal ? "*/1 * * * *" : "*/10 * * * *";
81	
82	  // アドバイス生成
83	  await scheduleCronJob(
84	    ADVICE_CRON_JOB_NAME,
85	    schedule,
86	    "/api/cron/generate-advice",
87	  );
88	
89	  // メモリー生成
90	  await scheduleCronJob(
91	    MEMORY_CRON_JOB_NAME,
92	    schedule,
93	    "/api/cron/generate-memory",
94	  );
95	}
96	
97	async function createQueueIfNotExists(queueName: string) {
98	  const result = (await db.execute(sql`
99			SELECT EXISTS (
100				SELECT 1 FROM pgmq.meta WHERE queue_name = ${queueName}
101			) as exists
102		`)) as unknown as { exists: boolean }[];
