CREATE TABLE "local"."glossaries" (
	"created_at" timestamp DEFAULT now() NOT NULL,
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"note" text DEFAULT '' NOT NULL,
	"project_id" uuid,
	"source_term" text NOT NULL,
	"target_term" text NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);

ALTER TABLE "local"."glossaries" ENABLE ROW LEVEL SECURITY;
CREATE TABLE "local"."project_members" (
	"created_at" timestamp DEFAULT now() NOT NULL,
	"project_id" uuid NOT NULL,
	"role" smallint DEFAULT 2 NOT NULL,
	"user_id" uuid NOT NULL,
	CONSTRAINT "project_members_project_id_user_id_pk" PRIMARY KEY("project_id","user_id")
);

ALTER TABLE "local"."project_members" ENABLE ROW LEVEL SECURITY;
CREATE TABLE "local"."projects" (
	"created_at" timestamp DEFAULT now() NOT NULL,
	"description" text DEFAULT '' NOT NULL,
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"owner_user_id" uuid NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	"visibility" smallint DEFAULT 2 NOT NULL
);

ALTER TABLE "local"."projects" ENABLE ROW LEVEL SECURITY;
CREATE TABLE "local"."segments" (
	"created_at" timestamp DEFAULT now() NOT NULL,
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"seq" integer NOT NULL,
	"source_text" text NOT NULL,
	"status" smallint DEFAULT 1 NOT NULL,
	"target_text" text,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	"work_id" uuid NOT NULL
);

ALTER TABLE "local"."segments" ENABLE ROW LEVEL SECURITY;
CREATE TABLE "local"."staffs" (
	"auth_user_id" uuid,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"first_name" text NOT NULL,
	"last_name" text NOT NULL,
	"staff_id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "staffs_auth_user_id_unique" UNIQUE("auth_user_id")
);

ALTER TABLE "local"."staffs" ENABLE ROW LEVEL SECURITY;
CREATE TABLE "local"."translation_memories" (
	"created_at" timestamp DEFAULT now() NOT NULL,
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"project_id" uuid NOT NULL,
	"source_embedding" "extensions.vector(1536)" NOT NULL,
	"source_text" text NOT NULL,
	"target_text" text NOT NULL
);

ALTER TABLE "local"."translation_memories" ENABLE ROW LEVEL SECURITY;
CREATE TABLE "local"."works" (
	"created_at" timestamp DEFAULT now() NOT NULL,
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"project_id" uuid NOT NULL,
	"source_file_name" text DEFAULT '' NOT NULL,
	"status" smallint DEFAULT 1 NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);

ALTER TABLE "local"."works" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "local"."glossaries" ADD CONSTRAINT "glossaries_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "local"."projects"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "local"."project_members" ADD CONSTRAINT "project_members_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "local"."projects"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "local"."project_members" ADD CONSTRAINT "project_members_user_id_staffs_staff_id_fk" FOREIGN KEY ("user_id") REFERENCES "local"."staffs"("staff_id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "local"."segments" ADD CONSTRAINT "segments_work_id_works_id_fk" FOREIGN KEY ("work_id") REFERENCES "local"."works"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "local"."translation_memories" ADD CONSTRAINT "translation_memories_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "local"."projects"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "local"."works" ADD CONSTRAINT "works_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "local"."projects"("id") ON DELETE cascade ON UPDATE no action;
CREATE INDEX "idx_glossaries_project" ON "local"."glossaries" USING btree ("project_id");
