1	"use client";
2	
3	import { useOnborda } from "onborda";
4	import { useCallback, useEffect, useSyncExternalStore } from "react";
5	import { steps } from "@/features/onboarding/constants/steps.universal";
6	
7	const STORAGE_KEY = "onboarding-completed";
8	const COMPLETE_EVENT = "onboarding-complete";
9	const RESET_EVENT = "onboarding-reset";
10	
11	export const TOUR_NAME = "main";
12	export const CUSTOMER_MENU_STEP_INDEX = 3;
13	
14	function getSnapshot(): boolean {
15	  try {
16	    return localStorage.getItem(STORAGE_KEY) === "true";
17	  } catch {
18	    return false;
19	  }
20	}
21	
22	function getServerSnapshot(): boolean {
23	  return false;
24	}
25	
26	function subscribe(callback: () => void): () => void {
27	  // 他タブからのストレージ変更を検知
28	  const handleStorageChange = (event: StorageEvent): void => {
29	    if (event.key === STORAGE_KEY) {
30	      callback();
31	    }
32	  };
33	
34	  // 同一タブからの完了/リセットイベントを検知
35	  const handleStateChange = (): void => {
36	    callback();
37	  };
38	
39	  globalThis.addEventListener("storage", handleStorageChange);
40	  globalThis.addEventListener(COMPLETE_EVENT, handleStateChange);
41	  globalThis.addEventListener(RESET_EVENT, handleStateChange);
42	  return (): void => {
43	    globalThis.removeEventListener("storage", handleStorageChange);
44	    globalThis.removeEventListener(COMPLETE_EVENT, handleStateChange);
45	    globalThis.removeEventListener(RESET_EVENT, handleStateChange);
46	  };
47	}
48	
49	interface UseOnboardingReturn {
50	  closeTour: () => void;
51	  complete: () => void;
52	  currentStep: number;
53	  isCompleted: boolean;
54	  isLastStep: boolean;
55	  refreshHighlight: () => void;
56	  reset: () => void;
57	  shouldShow: boolean;
58	  startTour: (tourName: string) => void;
59	}
60	
61	export function useOnboarding(): UseOnboardingReturn {
62	  const { currentStep, startOnborda, closeOnborda, isOnbordaVisible } =
63	    useOnborda();
64	  const isCompleted = useSyncExternalStore(
65	    subscribe,
66	    getSnapshot,
67	    getServerSnapshot,
68	  );
69	
70	  const isLastStep = currentStep === steps.length - 1;
