import type React from "react";
import { canManageProject, getProjectAccess } from "@/features/project/authz";
import { getCandidateUsers } from "./get-candidate-users";
import { getProjectMembers } from "./get-project-members";
import { MembersCard } from "./members-card.client";

export async function MembersCardContainer({
  projectId,
  userId,
}: {
  projectId: string;
  userId: string;
}): Promise<React.JSX.Element> {
  const [members, candidates, access] = await Promise.all([
    getProjectMembers(projectId),
    getCandidateUsers(),
    getProjectAccess(projectId, userId),
  ]);

  const canManage = access ? canManageProject(access) : false;
  const ownerUserId = access?.project.ownerUserId ?? "";

  return (
    <MembersCard
      candidates={candidates}
      canManage={canManage}
      members={members}
      ownerUserId={ownerUserId}
      projectId={projectId}
    />
  );
}

