input.content:
"use client";

import type React from "react";
import { SegmentStatus } from "@workspace/db/schema/segment";
import { Button } from "@workspace/ui/components/button";
import { Check, Combine, Scissors } from "lucide-react";
import Link from "next/link";
import { useCallback, useMemo, useRef, useState } from "react";
import { splitSentences } from "@/features/work/import/split-into-segments";
import { AssistPanel } from "./assist-panel.client";
import { confirmSegmentAction } from "./confirm-segment.action";
import type { SegmentDto } from "./get-work-segments";
import { mergeSegmentsAction } from "./merge-segments.action";
import { SegmentStatusDot } from "./segment-status-badge.universal";
import { splitSegmentAction } from "./split-segment.action";
import { updateSegmentAction } from "./update-segment.action";

type Mode = "merge" | "normal" | "split";

interface EditorProps {
  canEdit: boolean;
  initialSegments: SegmentDto[];
  projectId: string;
  workId: string;
  workName: string;
}

export function Editor({
  canEdit,
  initialSegments,
  projectId,
  workId,
  workName,
}: EditorProps): React.JSX.Element {
  const [segments, setSegmentsState] = useState<SegmentDto[]>(initialSegments);
  const segmentsRef = useRef<SegmentDto[]>(initialSegments);
  const [selectedId, setSelectedId] = useState<string | null>(
    initialSegments[0]?.id ?? null,
  );
  const [mode, setMode] = useState<Mode>("normal");
  const [mergeSelected, setMergeSelected] = useState<Set<string>>(new Set());
  const [saved, setSaved] = useState(false);
  const [isConfirming, setIsConfirming] = useState(false);
  const [confirmError, setConfirmError] = useState<string | null>(null);
  const [structuralError, setStructuralError] = useState<string | null>(null);
  const dirtyRef = useRef<Set<string>>(new Set());

  const setSegments = useCallback((next: SegmentDto[]): void => {
    segmentsRef.current = next;
    setSegmentsState(next);
  }, []);

  const selectedSegment = useMemo(
    () => segments.find((segment) => segment.id === selectedId) ?? null,
    [segments, selectedId],
  );

  const progress = useMemo(() => {
    const total = segments.length;
    const confirmed = segments.filter(
      (segment) => segment.status === SegmentStatus.Confirmed,
    ).length;
    return { confirmed, total };
  }, [segments]);

  const persistTarget = useCallback(
    async (segmentId: string): Promise<void> => {
      const segment = segmentsRef.current.find(
        (item) => item.id === segmentId,
      );
      if (!segment) {
        return;
      }
      const result = await updateSegmentAction({
        projectId,
        segmentId,
        targetText: segment.targetText ?? "",
        workId,
      });
      if (result.success) {
        setSegments(
          segmentsRef.current.map((item) =>
            item.id === segmentId
              ? { ...item, status: result.data.status }
              : item,
          ),
        );
        setSaved(true);
      }
    },
    [projectId, workId, setSegments],
  );

  function updateLocalTarget(segmentId: string, value: string): void {
    dirtyRef.current.add(segmentId);
    setSaved(false);
    setSegments(
      segmentsRef.current.map((segment) =>
        segment.id === segmentId
          ? { ...segment, targetText: value }
          : segment,
      ),
    );
  }

  function handleBlur(segmentId: string): void {
    if (!dirtyRef.current.has(segmentId)) {
      return;
    }
    dirtyRef.current.delete(segmentId);
    void persistTarget(segmentId);
  }

  function handleSelect(segmentId: string): void {
    if (mode === "merge") {
      setMergeSelected((prev) => {
        const next = new Set(prev);
        if (next.has(segmentId)) {
          next.delete(segmentId);
        } else {
          next.add(segmentId);
        }
        return next;
      });
      return;
    }
    setSelectedId(segmentId);
  }

  async function handleApply(text: string): Promise<void> {
    if (!selectedId) {
      return;
    }
    updateLocalTarget(selectedId, text);
    dirtyRef.current.delete(selectedId);
    await persistTarget(selectedId);
  }

  async function handleConfirm(): Promise<void> {
    if (!selectedSegment) {
      return;
    }
    setConfirmError(null);
    setIsConfirming(true);
    if (dirtyRef.current.has(selectedSegment.id)) {
      dirtyRef.current.delete(selectedSegment.id);
      await persistTarget(selectedSegment.id);
    }
    const result = await confirmSegmentAction({
      projectId,
      segmentId: selectedSegment.id,
      workId,
    });
    setIsConfirming(false);
    if (result.success) {
      setSegments(
        segmentsRef.current.map((segment) =>
          segment.id === selectedSegment.id
            ? { ...segment, status: SegmentStatus.Confirmed }
            : segment,
        ),
      );
    } else {
      setConfirmError(result.error);
    }
  }

  function toggleMode(target: Mode): void {
    setStructuralError(null);
    setMergeSelected(new Set());
    setMode((current) => (current === target ? "normal" : target));
  }

  async function handleMerge(): Promise<void> {
    const ids = segments
      .filter((segment) => mergeSelected.has(segment.id))
      .map((segment) => segment.id);
    if (ids.length < 2) {
      return;
    }
    setStructuralError(null);
    const result = await mergeSegmentsAction({
      projectId,
      segmentIds: ids,
      workId,
    });
    if (result.success) {
      setSegments(result.data);
      setMergeSelected(new Set());
      setMode("normal");
      setSelectedId(ids[0] ?? null);
    } else {
      setStructuralError(result.error);
    }
  }

  async function handleSplit(
    segmentId: string,
    splitIndex: number,
  ): Promise<void> {
    setStructuralError(null);
    const result = await splitSegmentAction({
      projectId,
      segmentId,
      splitIndex,
      workId,
    });
    if (result.success) {
      setSegments(result.data);
    } else {
      setStructuralError(result.error);
    }
  }

  return (
    <div className="flex h-full flex-col">
      <div className="flex flex-wrap items-center gap-3 border-b bg-card px-4 py-2">
        <Button asChild size="sm" variant="ghost">
          <Link href={`/projects/${projectId}`}>← 戻る</Link>
        </Button>
        <span className="font-semibold">{workName}</span>
        <span className="text-xs text-muted-foreground">
          確定 {progress.confirmed}/{progress.total}
        </span>
        {saved && (
          <span className="text-xs text-green-600">● 自動保存しました</span>
        )}
        <div className="flex-1" />
        {canEdit && (
          <>
            <Button
              onClick={() => toggleMode("merge")}
              size="sm"
              variant={mode === "merge" ? "default" : "outline"}
            >
              <Combine className="size-4" />
              結合モード
            </Button>
            <Button
              onClick={() => toggleMode("split")}
              size="sm"
              variant={mode === "split" ? "default" : "outline"}
            >
              <Scissors className="size-4" />
              分割モード
            </Button>
          </>
        )}
      </div>

      {mode === "merge" && (
        <div className="flex items-center gap-3 border-b bg-amber-50 px-4 py-2 text-sm text-amber-900 dark:bg-amber-950 dark:text-amber-100">
          <span>
            結合したい<b>連続するセグメント</b>をクリックで選択してください
          </span>
          <span className="font-medium">
            {mergeSelected.size} 文 選択中
          </span>
          <div className="flex-1" />
          <Button
            disabled={mergeSelected.size < 2}
            onClick={handleMerge}
            size="sm"
          >
            <Combine className="size-4" />
            選択した文を結合
          </Button>
        </div>
      )}
      {mode === "split" && (
        <div className="border-b bg-amber-50 px-4 py-2 text-sm text-amber-900 dark:bg-amber-950 dark:text-amber-100">
          文の区切りに出る <Scissors className="inline size-3.5" /> を
          クリックすると、その位置で 2 文に分割します
        </div>
      )}
      {structuralError && (
        <div
          className="border-b bg-destructive/10 px-4 py-2 text-sm text-destructive"
          role="alert"
        >
          {structuralError}
        </div>
      )}

      <div className="flex min-h-0 flex-1">
        <div className="min-w-0 flex-1 overflow-auto bg-muted/30 p-3">
          <div className="grid grid-cols-[32px_1fr_1fr] gap-2 px-1 pb-2 text-[11px] tracking-wide text-muted-foreground uppercase">
            <div>#</div>
            <div>原文（日本語）</div>
            <div>訳文（英語）</div>
          </div>
          <div className="space-y-1.5">
            {segments.map((segment) => {
              const isSelected =
                mode === "normal" && segment.id === selectedId;
              const isMergeSelected = mergeSelected.has(segment.id);
              return (
                <div
                  className={`grid grid-cols-[32px_1fr_1fr] overflow-hidden rounded-md border bg-card ${
                    isSelected ? "border-ring ring-2 ring-ring/30" : ""
                  } ${isMergeSelected ? "border-ring bg-accent" : ""}`}
                  key={segment.id}
                  onClick={() => handleSelect(segment.id)}
                >
                  <div className="flex flex-col items-center gap-1 border-r bg-muted/50 pt-2 text-[11px] text-muted-foreground tabular-nums">
                    <SegmentStatusDot status={segment.status} />
                    {segment.seq}
                  </div>
                  <div className="border-r px-3 py-2 text-sm leading-relaxed">
                    {mode === "split" ? (
                      <SplitSource
                        onSplit={(index) => handleSplit(segment.id, index)}
                        text={segment.sourceText}
                      />
                    ) : (
                      segment.sourceText
                    )}
                  </div>
                  <div className="px-2 py-1">
                    <textarea
                      className="min-h-9 w-full resize-none bg-transparent px-1.5 py-1 text-sm leading-relaxed outline-none"
                      disabled={!canEdit || mode !== "normal"}
                      onBlur={() => handleBlur(segment.id)}
                      onChange={(event) =>
                        updateLocalTarget(segment.id, event.target.value)
                      }
                      onClick={(event) => event.stopPropagation()}
                      rows={1}
                      value={segment.targetText ?? ""}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <aside className="w-[380px] shrink-0 border-l bg-card">
          <AssistPanel
            canEdit={canEdit}
            confirmError={confirmError}
            isConfirming={isConfirming}
            onApply={handleApply}
            onConfirm={handleConfirm}
            projectId={projectId}
            segment={selectedSegment}
          />
        </aside>
      </div>
    </div>
  );
}

function SplitSource({
  onSplit,
  text,
}: {
  onSplit: (index: number) => void;
  text: string;
}): React.JSX.Element {
  const parts = splitSentences(text);

  return (
    <span>
      {parts.map((part, index) => (
        // 文の並びは安定しているため index キーで問題ない
        // eslint-disable-next-line react/no-array-index-key
        <span key={index}>
          {part}
          {index < parts.length - 1 && (
            <button
              aria-label="ここで分割"
              className="mx-0.5 inline-flex size-4 items-center justify-center rounded border border-amber-300 bg-amber-100 align-middle text-amber-700 hover:bg-amber-500 hover:text-white"
              onClick={(event) => {
                event.stopPropagation();
                onSplit(index);
              }}
              type="button"
            >
              <Scissors className="size-2.5" />
            </button>
          )}
        </span>
      ))}
    </span>
  );
