"use client";

import type React from "react";
import { SegmentStatus } from "@workspace/db/schema/segment";
import { Button } from "@workspace/ui/components/button";
import { Check, Combine, Scissors } from "lucide-react";
import Link from "next/link";
import { useCallback, useMemo, useRef, useState } from "react";
import { splitSentences } from "@/features/work/import/split-into-segments";
import { AssistPanel } from "./assist-panel.client";
import { confirmSegmentAction } from "./confirm-segment.action";
import type { SegmentDto } from "./get-work-segments";
import { mergeSegmentsAction } from "./merge-segments.action";
import { SegmentStatusDot } from "./segment-status-badge.universal";
import { splitSegmentAction } from "./split-segment.action";
import { updateSegmentAction } from "./update-segment.action";

type Mode = "merge" | "normal" | "split";

interface EditorProps {
  canEdit: boolean;
  initialSegments: SegmentDto[];
  projectId: string;
  workId: string;
  workName: string;
}

export function Editor({
  canEdit,
  initialSegments,
  projectId,
  workId,
  workName,
}: EditorProps): React.JSX.Element {
  const [segments, setSegmentsState] = useState<SegmentDto[]>(initialSegments);
  const segmentsRef = useRef<SegmentDto[]>(initialSegments);
  const [selectedId, setSelectedId] = useState<string | null>(
    initialSegments[0]?.id ?? null,
  );
  const [mode, setMode] = useState<Mode>("normal");
  const [mergeSelected, setMergeSelected] = useState<Set<string>>(new Set());
  const [saved, setSaved] = useState(false);
  const [isConfirming, setIsConfirming] = useState(false);
  const [confirmError, setConfirmError] = useState<string | null>(null);
  const [structuralError, setStructuralError] = useState<string | null>(null);
  const dirtyRef = useRef<Set<string>>(new Set());

  const setSegments = useCallback((next: SegmentDto[]): void => {
    segmentsRef.current = next;
    setSegmentsState(next);
  }, []);

  const selectedSegment = useMemo(
    () => segments.find((segment) => segment.id === selectedId) ?? null,
    [segments, selectedId],
  );

  const progress = useMemo(() => {
    const total = segments.length;
    const confirmed = segments.filter(
      (segment) => segment.status === SegmentStatus.Confirmed,
    ).length;
    return { confirmed, total };
  }, [segments]);

  const persistTarget = useCallback(
    async (segmentId: string): Promise<void> => {
      const segment = segmentsRef.current.find(
        (item) => item.id === segmentId,
      );
      if (!segment) {
        return;
      }
      const result = await updateSegmentAction({
        projectId,
        segmentId,
        targetText: segment.targetText ?? "",
        workId,
      });
      if (result.success) {
        setSegments(
          segmentsRef.current.map((item) =>
            item.id === segmentId
              ? { ...item, status: result.data.status }
              : item,
          ),
        );
        setSaved(true);
      }
    },
    [projectId, workId, setSegments],
  );

  function updateLocalTarget(segmentId: string, value: string): void {
    dirtyRef.current.add(segmentId);
    setSaved(false);
    setSegments(
      segmentsRef.current.map((segment) =>
        segment.id === segmentId
          ? { ...segment, targetText: value }
          : segment,
      ),
    );
  }

  function handleBlur(segmentId: string): void {
    if (!dirtyRef.current.has(segmentId)) {
      return;
    }
    dirtyRef.current.delete(segmentId);
    void persistTarget(segmentId);
  }

  function handleSelect(segmentId: string): void {
    if (mode === "merge") {
      setMergeSelected((prev) => {
        const next = new Set(prev);
        if (next.has(segmentId)) {
          next.delete(segmentId);
        } else {
          next.add(segmentId);
        }
        return next;
      });
      return;
    }
    setSelectedId(segmentId);
  }

  async function handleApply(text: string): Promise<void> {
    if (!selectedId) {
      return;
    }
    updateLocalTarget(selectedId, text);
    dirtyRef.current.delete(selectedId);
    await persistTarget(selectedId);
  }

  async function handleConfirm(): Promise<void> {
    if (!selectedSegment) {
      return;
    }
    setConfirmError(null);
    setIsConfirming(true);
    if (dirtyRef.current.has(selectedSegment.id)) {
      dirtyRef.current.delete(selectedSegment.id);
      await persistTarget(selectedSegment.id);
    }
    const result = await confirmSegmentAction({
      projectId,
      segmentId: selectedSegment.id,
      workId,
    });
    setIsConfirming(false);
    if (result.success) {
      setSegments(
        segmentsRef.current.map((segment) =>
          segment.id === selectedSegment.id
            ? { ...segment, status: SegmentStatus.Confirmed }
            : segment,
        ),
      );
    } else {
      setConfirmError(result.error);
    }
  }

  function toggleMode(target: Mode): void {
    setStructuralError(null);
    setMergeSelected(new Set());
    setMode((current) => (current === target ? "normal" : target));
  }

  async function handleMerge(): Promise<void> {
    const ids = segments
      .filter((segment) => mergeSelected.has(segment.id))
      .map((segment) => segment.id);
    if (ids.length < 2) {
      return;
    }
    setStructuralError(null);
    const result = await mergeSegmentsAction({
      projectId,
      segmentIds: ids,
      workId,
    });
    if (result.success) {
      setSegments(result.data);
      setMergeSelected(new Set());
      setMode("normal");
      setSelectedId(ids[0] ?? null);
    } else {
      setStructuralError(result.error);
    }
  }

  async function handleSplit(
    segmentId: string,
    splitIndex: number,
  ): Promise<void> {
    setStructuralError(null);
    const result = await splitSegmentAction({
      projectId,
      segmentId,
      splitIndex,
      workId,
    });
    if (result.success) {
      setSegments(result.data);
    } else {
      setStructuralError(result.error);
    }
