import type React from "react";
import { notFound } from "next/navigation";
import { getUserStaffId } from "@/features/auth/get-user-staff-id";
import { canEditProject, getProjectAccess } from "@/features/project/authz";
import { Editor } from "@/features/segment/editor.client";
import { getWorkSegments } from "@/features/segment/get-work-segments";

export default async function Page({
  params,
}: PageProps<"/projects/[projectId]/works/[workId]">): Promise<React.JSX.Element> {
  const { projectId, workId } = await params;
  const userId = await getUserStaffId();

  if (!userId) {
    notFound();
  }

  const access = await getProjectAccess(projectId, userId);

  if (!access) {
    notFound();
  }

  const data = await getWorkSegments(workId);

  if (!data || data.work.projectId !== projectId) {
    notFound();
  }

  return (
    <div className="h-full">
      <Editor
        canEdit={canEditProject(access)}
        initialSegments={data.segments}
        projectId={projectId}
        workId={workId}
        workName={data.work.name}
      />
    </div>
  );
}

