import { db } from "@workspace/db/client";
import type { ProjectVisibility } from "@workspace/db/schema/project";
import { projectsTable } from "@workspace/db/schema/project";
import { eq } from "drizzle-orm";
import { cache } from "react";
import { cacheLife, cacheTag } from "next/cache";
import { ProjectTag } from "@/features/project/tag";

export interface ProjectDetail {
  description: string;
  id: string;
  name: string;
  ownerUserId: string;
  visibility: ProjectVisibility;
}

export const getProjectDetail = cache(
  async (projectId: string): Promise<ProjectDetail | null> => {
    "use cache";
    cacheLife("permanent");
    cacheTag(ProjectTag.Detail(projectId));

    const project = await db.query.projectsTable.findFirst({
      where: eq(projectsTable.id, projectId),
    });

    if (!project) {
      return null;
    }

    return {
      description: project.description,
      id: project.id,
      name: project.name,
      ownerUserId: project.ownerUserId,
      visibility: project.visibility as ProjectVisibility,
    };
  },
);

