import { db } from "@workspace/db/client";
import type { SelectProject } from "@workspace/db/schema/project";
import {
  ProjectMemberRole,
  ProjectVisibility,
  projectMembersTable,
  projectsTable,
} from "@workspace/db/schema/project";
import { and, eq } from "drizzle-orm";

export interface ProjectAccess {
  /** メンバーの場合のロール。Public プロジェクトを非メンバーが閲覧する場合は null */
  role: ProjectMemberRole | null;
  project: SelectProject;
  isMember: boolean;
}

/**
 * ユーザーが対象プロジェクトにアクセスできるか判定する。
 * - Public: ログインユーザー全員が閲覧可
 * - Private: project_members に登録されたユーザーのみ
 *
 * アクセス不可（存在しない / Private で非メンバー）の場合は null を返す。
 */
export async function getProjectAccess(
  projectId: string,
  userId: string,
): Promise<ProjectAccess | null> {
  const project = await db.query.projectsTable.findFirst({
    where: eq(projectsTable.id, projectId),
  });

  if (!project) {
    return null;
  }

  const membership = await db.query.projectMembersTable.findFirst({
    where: and(
      eq(projectMembersTable.projectId, projectId),
      eq(projectMembersTable.userId, userId),
    ),
  });

  if (membership) {
    return {
      isMember: true,
      project,
      role: membership.role as ProjectMemberRole,
    };
  }

  if (project.visibility === ProjectVisibility.Public) {
    return { isMember: false, project, role: null };
  }

  return null;
}

/** 編集権限（Owner / Editor）を持つか */
export function canEditProject(access: ProjectAccess): boolean {
  return (
    access.role === ProjectMemberRole.Owner ||
    access.role === ProjectMemberRole.Editor
  );
}

/** 管理権限（Owner のみ：メンバー管理・削除・可視性変更） */
export function canManageProject(access: ProjectAccess): boolean {
  return access.role === ProjectMemberRole.Owner;
}

import { db } from "@workspace/db/client";
import type { SegmentStatus } from "@workspace/db/schema/segment";
import { segmentsTable } from "@workspace/db/schema/segment";
import type { WorkStatus } from "@workspace/db/schema/work";
import { worksTable } from "@workspace/db/schema/work";
import { asc, eq } from "drizzle-orm";
import { cacheLife, cacheTag } from "next/cache";
import { WorkTag } from "@/features/work/tag";

export interface SegmentDto {
  id: string;
  seq: number;
  sourceText: string;
  status: SegmentStatus;
  targetText: string | null;
}

export interface WorkWithSegments {
  segments: SegmentDto[];
  work: {
    id: string;
    name: string;
    projectId: string;
    status: WorkStatus;
  };
}

export async function getWorkSegments(
  workId: string,
): Promise<WorkWithSegments | null> {
  "use cache";
  cacheLife("permanent");
  cacheTag(WorkTag.SegmentsByWorkId(workId), WorkTag.Detail(workId));

  const work = await db.query.worksTable.findFirst({
    where: eq(worksTable.id, workId),
  });

  if (!work) {
    return null;
  }

  const segments = await db
    .select({
      id: segmentsTable.id,
      seq: segmentsTable.seq,
      sourceText: segmentsTable.sourceText,
      status: segmentsTable.status,
      targetText: segmentsTable.targetText,
    })
    .from(segmentsTable)
    .where(eq(segmentsTable.workId, workId))
    .orderBy(asc(segmentsTable.seq));

  return {
    segments: segments.map((segment) => ({
      id: segment.id,
      seq: segment.seq,
      sourceText: segment.sourceText,
      status: segment.status as SegmentStatus,
      targetText: segment.targetText,
    })),
    work: {
      id: work.id,
